if(type==='floorlamp'){cyl(g,.2,.22,.035,0,.018,0,brass);rod(g,[0,.035,0],[0,1.37,0],.013,brass);const shade=new T.Mesh(new T.CylinderGeometry(.19,.32,.4,72,1,true),mats.fabric);shade.position.y=1.49;shade.castShadow=true;g.add(shade);cyl(g,.28,.28,.015,0,1.29,0,'fabric');cyl(g,.055,.055,.13,0,1.41,0,'glow');const l=new T.PointLight('#ffdbaa',1.6,3,2);l.position.y=1.4;g.add(l);bulbs.push(l);}
if(type==='lantern'){const geo=new T.SphereGeometry(1,64,48),v=geo.attributes.position;for(let i=0;i<v.count;i++){const x=v.getX(i),y=v.getY(i),z=v.getZ(i),a=Math.atan2(z,x),fold=1+.014*Math.cos(a*24);v.setXYZ(i,x*.22*fold,y*.3,z*.22*fold)}geo.computeVertexNormals();const skin=new T.MeshPhysicalMaterial({color:'#f3ddb4',roughness:.83,transmission:.1,thickness:.01,side:T.DoubleSide});const mesh=new T.Mesh(geo,skin);mesh.position.y=.39;g.add(mesh);cyl(g,.12,.13,.05,0,.1,0,'wood');cyl(g,.08,.08,.045,0,.71,0,'wood');curvedRod(g,[[-.06,.73,0],[-.09,.83,0],[0,.88,0],[.09,.83,0],[.06,.73,0]],.006,brass);const l=new T.PointLight('#ffbe6c',1,2,2);l.position.y=.39;g.add(l);bulbs.push(l);}
