function snapshot(){return{...state,colors:Object.fromEntries(Object.keys(options).map(k=>[k,'#'+mats[k].color.getHexString()])),items:movable.map(g=>({type:g.userData.type,x:g.position.x,z:g.position.z,yaw:g.rotation.y}))}}
