function load(s){if(!s||!Array.isArray(s.items)||s.items.length>60)return;state={mood:s.mood??0,hour:s.hour??15.5,lights:s.lights??true};for(let [k,c]of Object.entries(s.colors||{}))if(mats[k]&&/^#[0-9a-f]{6}$/i.test(c))mats[k].color.set(c);mats.floor.color.copy(mats.wood.color).lerp(new T.Color('#e5d5b8'),.3);for(let g of [...movable])scene.remove(g);movable.length=0;for(let i of s.items)if(names[i.type]&&[i.x,i.z,i.yaw].every(Number.isFinite))furniture(i.type,T.MathUtils.clamp(i.x,-2.2,2.1),T.MathUtils.clamp(i.z,-4.1,4.2),i.yaw);select(null);updateUI();lighting()}
const initial=snapshot();
function updateUI(){$('#clock').textContent=`${String(Math.floor(state.hour)).padStart(2,'0')}:${String(Math.round((state.hour%1)*60)).padStart(2,'0')}`;$('#hour').value=state.hour;$('#lights').checked=state.lights;$('#moodName').textContent=state.mood<0?'Tùy chỉnh':presets[state.mood].name;document.querySelectorAll('.mood').forEach((e,i)=>e.classList.toggle('active',i===state.mood));document.querySelectorAll('.swatch').forEach(e=>e.classList.toggle('active',mats[e.dataset.mat].color.getHexString()===e.dataset.color.slice(1)));document.querySelectorAll('#times button').forEach(e=>e.classList.toggle('active',+e.dataset.hour===state.hour));$('#undo').disabled=!history.length}
function lighting(){const daylight=Math.max(0,Math.sin((state.hour-6)/12*Math.PI));sun.intensity=daylight*3.5;sun.position.set(-7,Math.max(.3,daylight*8),(state.hour-12)*.8);sun.color.set(state.hour>16?'#ffdbab':'#fff5e4');hemisphere.intensity=.18+daylight*.7;scene.environmentIntensity=.18+daylight*.32;artificial.forEach((l,i)=>l.intensity=state.lights?(i<5?1.8:(daylight>.2?.16:.65)):0);bulbs.forEach(l=>l.visible=state.lights);mats.glow.emissiveIntensity=state.lights?1.5:0;scene.background.set(daylight>.2?'#d7ddcf':'#303a35');scene.fog.color.copy(scene.background);renderer.toneMappingExposure=1.2;updateUI()}
function setMood(i){remember();state.mood=i;const p=presets[i];Object.keys(options).forEach((k,j)=>mats[k].color.set(p.colors[j]));mats.floor.color.copy(mats.wood.color).lerp(new T.Color('#e5d5b8'),.3);state.hour=p.h;lighting()}
$('#moods').innerHTML=presets.map((p,i)=>`<button class="mood" data-mood="${i}"><span class="palette">${p.colors.map(c=>`<i style="background:${c}"></i>`).join('')}</span>${p.name}</button>`).join('');$('#moods').onclick=e=>{const b=e.target.closest('[data-mood]');if(b)setMood(+b.dataset.mood)};
$('#materials').innerHTML=Object.entries(options).map(([k,cs])=>`<div class="material-row"><span class="material-label">${labels[k]}</span><div class="swatches">${cs.map((c,i)=>`<button class="swatch" aria-label="${labels[k]} màu ${i+1}" title="${labels[k]} ${c}" data-mat="${k}" data-color="${c}" style="background:${c}"></button>`).join('')}</div></div>`).join('');$('#materials').onclick=e=>{const b=e.target.closest('.swatch');if(!b)return;remember();mats[b.dataset.mat].color.set(b.dataset.color);if(b.dataset.mat==='wood')mats.floor.color.copy(mats.wood.color).lerp(new T.Color('#e5d5b8'),.3);state.mood=-1;updateUI()};
$('#hour').onpointerdown=remember;$('#hour').onkeydown=e=>{if(e.key.startsWith('Arrow'))remember()};$('#hour').oninput=e=>{state.hour=+e.target.value;lighting()};$('#times').onclick=e=>{if(e.target.dataset.hour){remember();state.hour=+e.target.dataset.hour;lighting()}};$('#lights').onchange=e=>{remember();state.lights=e.target.checked;lighting()};
$('#furniture').innerHTML=Object.entries(names).map(([k,n])=>`<button data-type="${k}"><span class="furn-icon" aria-hidden="true">${icons[k]||'◇'}</span>${n}</button>`).join('');$('#furniture').onclick=e=>{const b=e.target.closest('[data-type]');if(!b)return;if(movable.length>=60)return toast('Phòng đã có 60 đồ vật. Bỏ bớt đồ để thêm món mới.');remember();const obj=furniture(b.dataset.type,-1.05,2.9);select(obj);lighting();toast('Đã thêm '+names[b.dataset.type])};
function select(g){selected=g;$('#selected').hidden=!g;if(g)$('#selectedName').textContent=names[g.userData.type];}$('#deselect').onclick=()=>select(null);$('#rotate').onclick=()=>{if(selected){remember();selected.rotation.y+=Math.PI/4}};$('#remove').onclick=()=>{if(selected){remember();scene.remove(selected);movable.splice(movable.indexOf(selected),1);select(null)}};
const ray=new T.Raycaster(),pointer=new T.Vector2(),floorPlane=new T.Plane(new T.Vector3(0,1,0),0),hit=new T.Vector3(),offset=new T.Vector3();let down=null;
function aim(e){const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,cam)}
renderer.domElement.addEventListener('pointerdown',e=>{if(e.button!==0)return;aim(e);const h=ray.intersectObjects(movable,true)[0];down=[e.clientX,e.clientY];if(h){select(h.object.userData.owner);ray.ray.intersectPlane(floorPlane,hit);offset.copy(selected.position).sub(hit);dragging=true;controls.enabled=false;remember();renderer.domElement.setPointerCapture(e.pointerId)}else select(null)},true);
renderer.domElement.addEventListener('pointermove',e=>{if(!dragging||!selected)return;aim(e);if(ray.ray.intersectPlane(floorPlane,hit)){selected.position.x=T.MathUtils.clamp(hit.x+offset.x,-2.13,1.34);selected.position.z=T.MathUtils.clamp(hit.z+offset.z,-3.3,4.1)}});
function stop(){dragging=false;controls.enabled=true;down=null}renderer.domElement.addEventListener('pointerup',stop);renderer.domElement.addEventListener('pointercancel',stop);
const views={entry:[[.05,1.72,4.8],[0,1.4,-2.4]],lounge:[[1.2,1.8,4.8],[-1.1,.65,1.1]],shelf:[[-1.6,2.25,5.4],[2,1.6,-.9]],overview:[[8.7,7.8,10.8],[0,0,0]]};let tween=null;
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{let v=views[b.dataset.view];tween={start:performance.now(),from:cam.position.clone(),to:new T.Vector3(...v[0]),targetFrom:controls.target.clone(),targetTo:new T.Vector3(...v[1])};document.querySelectorAll('[data-view]').forEach(a=>a.classList.toggle('active',a===b));});
$('#undo').onclick=()=>{const s=history.pop();if(s)load(s)};$('#reset').onclick=()=>{remember();load(initial);toast('Đã khôi phục bố trí ban đầu')};
let timeout;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timeout);timeout=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
$('#save').onclick=()=>{composer.render();renderer.domElement.toBlob(blob=>{if(!blob)return toast('Không xuất được ảnh');const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Hoi-An-Room-Studio.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000);toast('Đã xuất ảnh phối cảnh')})};
function encode(s){return btoa(unescape(encodeURIComponent(JSON.stringify(s))))}$('#share').onclick=async()=>{location.hash='room='+encode(snapshot());try{await navigator.clipboard.writeText(location.href);toast('Đã sao chép link chứa thiết kế này')}catch{toast('Thiết kế đã nằm trong đường dẫn. Sao chép thanh địa chỉ để chia sẻ.')}};
for(let id of ['reference','photo'])$('#'+id).onclick=()=>$('#refDialog').showModal();$('#closeRef').onclick=()=>$('#refDialog').close();$('#refDialog').onclick=e=>{if(e.target===e.currentTarget)e.currentTarget.close()};
document.addEventListener('keydown',e=>{if(e.target.matches('input,button')||$('#refDialog').open)return;if(e.key==='Escape')select(null);if(e.key.toLowerCase()==='r'&&selected)$('#rotate').click();if(e.key==='Delete'&&selected)$('#remove').click();if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();$('#undo').click()}if(selected&&e.key.startsWith('Arrow')){e.preventDefault();remember();selected.position.x=T.MathUtils.clamp(selected.position.x+(e.key==='ArrowRight'?.1:e.key==='ArrowLeft'?-.1:0),-2.13,1.34);selected.position.z=T.MathUtils.clamp(selected.position.z+(e.key==='ArrowDown'?.1:e.key==='ArrowUp'?-.1:0),-3.3,4.1)}});
new ResizeObserver(()=>{const {width,height}=world.getBoundingClientRect();renderer.setSize(width,height);composer.setSize(width,height);ao.setSize(Math.round(width),Math.round(height));cam.aspect=width/height;cam.updateProjectionMatrix()}).observe(world);
function frame(time){requestAnimationFrame(frame);if(tween){let t=Math.min(1,(time-tween.start)/800);t=t*t*(3-2*t);cam.position.lerpVectors(tween.from,tween.to,t);controls.target.lerpVectors(tween.targetFrom,tween.targetTo,t);if(t===1)tween=null}overhead.visible=cam.position.y<3.5;controls.update();composer.render()}
try{if(location.hash.startsWith('#room='))load(JSON.parse(decodeURIComponent(escape(atob(location.hash.slice(6))))))}catch{toast('Link thiết kế không hợp lệ; đã mở phòng nguyên bản')}
await Promise.allSettled(textureJobs);
function catalogThumbnails(){const tr=new T.WebGLRenderer({antialias:true,alpha:true});tr.setSize(168,120);tr.setPixelRatio(1);tr.toneMapping=T.ACESFilmicToneMapping;tr.toneMappingExposure=1.25;const ts=new T.Scene();ts.environment=scene.environment;ts.environmentIntensity=.6;ts.add(new T.HemisphereLight('#fff8ef','#77654e',2));const light=new T.DirectionalLight('#fff2de',3);light.position.set(-3,5,4);ts.add(light);const camera=new T.PerspectiveCamera(35,1.4,.01,30);for(const type of Object.keys(names)){const group=new T.Group();buildFurniture(group,type);ts.add(group);const bb=new T.Box3().setFromObject(group),size=bb.getSize(new T.Vector3()),center=bb.getCenter(new T.Vector3()),r=Math.max(size.x,size.y,size.z);camera.position.copy(center).add(new T.Vector3(r*1.5,r*.85,r*1.8));camera.lookAt(center);tr.render(ts,camera);const img=document.createElement('img');img.src=tr.domElement.toDataURL();img.alt='';const button=$(`[data-type="${type}"]`);button.querySelector('.furn-icon').replaceWith(img);ts.remove(group);}tr.dispose();}
catalogThumbnails();lighting();$('#loading').remove();frame(0);
window.roomStudio={getState:snapshot,setMood,setHour:h=>{remember();state.hour=T.MathUtils.clamp(h,6,22);lighting()},reset:()=>load(initial)};
if(navigator.modelContext?.registerTool){navigator.modelContext.registerTool({name:'get_room_design',description:'Read current room materials, lighting and furniture placement',inputSchema:{type:'object',properties:{}},execute:async()=>({content:[{type:'text',text:JSON.stringify(snapshot())}]})});navigator.modelContext.registerTool({name:'set_room_mood',description:'Choose the room palette: 0 original, 1 light natural, 2 warm evening',inputSchema:{type:'object',properties:{mood:{type:'integer',minimum:0,maximum:2}},required:['mood']},execute:async({mood})=>{setMood(mood);return{content:[{type:'text',text:JSON.stringify(snapshot())}]}}})}
